CREATE OR REPLACE VIEW DBP_MSI_VIEW_VIS.MV_WUP_PER_1 as
   SELECT
  coalesce(ist.wup_id, vj.wup_id) as wup_id, coalesce(ist.nb_id, vj.nb_id) as nb_id, coalesce(ist.mandant_id, vj.mandant_id) as mandant_id, coalesce(ist.kjmo, vj.kjmo + 100)   as kjmo, ist.verkaufsflaeche            as verkaufsflaeche, ist.betriebsflaeche            as betriebsflaeche, ist.konzessionaersflaeche      as konzessionaersflaeche, ist.parkplatz_anz_ges          as parkplatz_anz_ges, ist.parkplatz_anz_kl           as parkplatz_anz_kl, ist.eigentum_fg                as eigentum_fg, ist.einwohner_anz_1km          as einwohner_anz_1km, ist.einwohner_anz_einzug       as einwohner_anz_einzug, ist.getraenkemarkt_fg          as getraenkemarkt_fg, ist.kundenfaktor               as kundenfaktor, ist.preiskategorie_food        as preiskategorie_food, ist.preiskategorie_nonfood     as preiskategorie_nonfood, ist.sortkategorie_food         as sortkategorie_food, ist.sortkategorie_nonfood      as sortkategorie_nonfood, ist.auflage_tip                as auflage_tip, ist.wrg_id                     as umsatz_wrg, ist.mietrentabiltaet           as mietrentabiltaet, ist.breakevenumsatz            as breakevenumsatz, ist.systemrentabilitaet        as systemrentabilitaet, ist.umsatz_ea                  as umsatz_ea, ist.umsatz_woche               as umsatz_woche, vj.verkaufsflaeche            as verkaufsflaeche_vj, vj.betriebsflaeche          as betriebsflaeche_vj, vj.konzessionaersflaeche    as konzessionaersflaeche_vj, vj.parkplatz_anz_ges        as parkplatz_anz_ges_vj, vj.parkplatz_anz_kl         as parkplatz_anz_kl_vj, vj.eigentum_fg              as eigentum_fg_vj, vj.einwohner_anz_1km        as einwohner_anz_1km_vj, vj.einwohner_anz_einzug     as einwohner_anz_einzug_vj, vj.getraenkemarkt_fg        as getraenkemarkt_fg_vj, vj.kundenfaktor             as kundenfaktor_vj, vj.preiskategorie_food      as preiskategorie_food_vj, vj.preiskategorie_nonfood   as preiskategorie_nonfood_vj, vj.sortkategorie_food       as sortkategorie_food_vj, vj.sortkategorie_nonfood    as sortkategorie_nonfood_vj, vj.auflage_tip              as auflage_tip_vj, vj.mietrentabiltaet         as mietrentabiltaet_vj, vj.breakevenumsatz          as breakevenumsatz_vj, vj.systemrentabilitaet      as systemrentabilitaet_vj, vj.umsatz_ea                as umsatz_ea_vj, vj.umsatz_woche             as umsatz_woche_vj

   FROM dbp_view.v_wup_per_1 ist
   FULL OUTER join dbp_view.v_wup_per_1 vj
   ON ist.mandant_id = vj.mandant_id
   and ist.wup_id = vj.wup_id
   and ist.nb_id = vj.nb_id
   and ist.wrg_id = vj.wrg_id
   and ist.kjmo = vj.kjmo + 100;